# AUTO-GENERATED by _add_daily_fortune.py + Step 3 variation
"""
Daily result → language-ready response.

Step 3: Seed 기반 변형 선택 지원.
  - content_map의 값이 리스트면 seed로 pick_variant
  - dict면 기존처럼 그대로 사용 (하위호환)
"""
from app.services.content.loader import load_pack
from app.services.variation import pick_variant, make_seed


def _select_content(entry, *, user_id, birth_date, date_str, ten_god):
    """entry가 dict 또는 list일 수 있음. list면 seed로 변형 선택."""
    if isinstance(entry, dict):
        return entry
    if isinstance(entry, list) and entry:
        seed = make_seed(
            user_id=user_id,
            birth_date=birth_date,
            scope="daily",
            discriminator=f"{date_str}|{ten_god}",
        )
        return pick_variant(entry, seed_parts=seed)
    return {}


def write_daily_section(
    daily_results: list,
    lang: str = "en",
    *,
    user_id: str | None = None,
    birth_date: str | None = None,
) -> dict:
    pack = load_pack(lang, "daily")
    content_map = pack.get("DAILY_THEME_CONTENT", {})
    default_theme = pack.get("DEFAULT_DAILY_THEME", {})
    grade_label = pack.get("GRADE_LABEL", {})
    hero_tpl = pack.get("DAILY_HERO_TEMPLATE", "{date}")

    items = []
    for r in daily_results:
        tg = r["ten_god"]
        date_str = r["date"]
        raw = content_map.get(tg, default_theme)
        content = _select_content(
            raw,
            user_id=user_id,
            birth_date=birth_date,
            date_str=date_str,
            ten_god=tg,
        )
        if not content:
            content = default_theme

        items.append({
            "date": date_str,
            "day_pillar": r["day_pillar"],
            "ten_god": tg,
            "score": r["score"],
            "grade": r["grade"],
            "grade_label": grade_label.get(r["grade"], r["grade"]),
            "name": content.get("name", ""),
            "headline": content.get("headline", ""),
            "body": content.get("body", ""),
            "watch_for": content.get("watch_for", ""),
            "lean_into": content.get("lean_into", ""),
        })

    start_date = items[0]["date"] if items else ""
    hero = hero_tpl.format(date=start_date)

    return {
        "meta": {
            "lang": lang,
            "schema_version": "1.0",
            "days": len(items),
            "start_date": start_date or None,
        },
        "hero": hero,
        "items": items,
    }
